/** Finite choices whose displayed question is generated by the host. */
export type ClarificationChoice = {
  kind: "field-required";
  field: import("../evolution/field-identity.js").FieldReference;
} & ({ scope: "action-input"; action: string } | { scope: "task-presence" });

export function clarificationChoiceSchema(field: Record<string, unknown>) {
  return {
    anyOf: ["action-input", "task-presence"].map((scope) => ({
      type: "object",
      additionalProperties: false,
      required: [
        "kind",
        "scope",
        "field",
        ...(scope === "action-input" ? ["action"] : []),
      ],
      properties: {
        kind: { type: "string", enum: ["field-required"] },
        scope: { type: "string", enum: [scope] },
        field,
        ...(scope === "action-input"
          ? { action: { type: "string", minLength: 1, maxLength: 120 } }
          : {}),
      },
    })),
  };
}

export function clarificationChoiceQuestion(
  choice: ClarificationChoice,
  sourceQuote: string,
  ordinal: number,
) {
  const field =
    choice.field.kind === "new" ? choice.field.name : choice.field.targetId;
  const scope =
    choice.scope === "action-input"
      ? `执行“${choice.action}”时的“${field}”输入`
      : `任务本身的“${field}”字段`;
  return `请确认第 ${ordinal} 项原文“${sourceQuote}”中的未决要求：${scope}必须填写，还是可以留空？`;
}
